import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"es/cli/run.md","filePath":"es/cli/run.md","lastUpdated":1784903584000}'),r={name:"es/cli/run.md"};function n(d,a,s,l,c,u){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="proposito" tabindex="-1">Propósito <a class="header-anchor" href="#proposito" aria-label="Permalink to &quot;Propósito&quot;">​</a></h2><p>Iniciar el explorador de API <strong>TUI (Interfaz de Usuario de Terminal)</strong> interactivo. Es una aplicación de pantalla completa para buscar, navegar, inspeccionar e invocar endpoints de API sin salir de la terminal.</p><h2 id="cuando-usarlo" tabindex="-1">Cuándo usarlo <a class="header-anchor" href="#cuando-usarlo" aria-label="Permalink to &quot;Cuándo usarlo&quot;">​</a></h2><ul><li>Desea explorar sus APIs de forma interactiva</li><li>Necesita buscar un endpoint específico en todas las especificaciones</li><li>Desea navegar por la jerarquía especificación → colección → etiqueta → endpoint</li><li>Desea probar una llamada a la API antes de configurar el servidor MCP</li></ul><h2 id="sintaxis" tabindex="-1">Sintaxis <a class="header-anchor" href="#sintaxis" aria-label="Permalink to &quot;Sintaxis&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="argumentos" tabindex="-1">Argumentos <a class="header-anchor" href="#argumentos" aria-label="Permalink to &quot;Argumentos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argumento</th><th>Posición</th><th>Requerido</th><th>Descripción</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>No</td><td>Directorio del espacio de trabajo. Si se omite, se resuelve mediante reglas de resolución de ruta.</td></tr></tbody></table><h2 id="banderas" tabindex="-1">Banderas <a class="header-anchor" href="#banderas" aria-label="Permalink to &quot;Banderas&quot;">​</a></h2><p>Ninguna.</p><h2 id="modos" tabindex="-1">Modos <a class="header-anchor" href="#modos" aria-label="Permalink to &quot;Modos&quot;">​</a></h2><h3 id="modo-de-busqueda" tabindex="-1">Modo de búsqueda <a class="header-anchor" href="#modo-de-busqueda" aria-label="Permalink to &quot;Modo de búsqueda&quot;">​</a></h3><p>Búsqueda de texto completo en todos los endpoints de todas las especificaciones. Admite filtrado por método HTTP, etiqueta y ruta.</p><ul><li>Escriba una consulta para buscar nombres, rutas y descripciones de endpoints</li><li>Filtre resultados por método (GET, POST, PUT, DELETE, etc.)</li><li>Vea los detalles del endpoint con una sola pulsación de tecla</li></ul><h3 id="modo-de-navegacion" tabindex="-1">Modo de navegación <a class="header-anchor" href="#modo-de-navegacion" aria-label="Permalink to &quot;Modo de navegación&quot;">​</a></h3><p>Navegación en árbol a través de la jerarquía de especificaciones:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Especificación → Colección → Etiqueta → Endpoint</span></span></code></pre></div><ul><li>Navegue hacia abajo en el árbol para encontrar endpoints específicos</li><li>Vea los detalles del endpoint (parámetros, cuerpo de solicitud, respuestas)</li><li>Invocar la API directamente desde la TUI</li></ul><h2 id="navegacion" tabindex="-1">Navegación <a class="header-anchor" href="#navegacion" aria-label="Permalink to &quot;Navegación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tecla</th><th>Acción</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Navegar arriba/abajo</td></tr><tr><td><code>Enter</code></td><td>Seleccionar o abrir</td></tr><tr><td><code>Esc</code></td><td>Retroceder</td></tr><tr><td><code>Tab</code></td><td>Cambiar entre los modos Búsqueda y Navegación</td></tr><tr><td><code>/</code></td><td>Enfocar entrada de búsqueda</td></tr><tr><td><code>q</code></td><td>Salir</td></tr></tbody></table><h2 id="verificacion-posterior-al-comando" tabindex="-1">Verificación posterior al comando <a class="header-anchor" href="#verificacion-posterior-al-comando" aria-label="Permalink to &quot;Verificación posterior al comando&quot;">​</a></h2><p>La TUI carga todas las especificaciones del espacio de trabajo. Si una especificación falla al cargar, se muestra un mensaje de error en la interfaz.</p><h2 id="matices" tabindex="-1">Matices <a class="header-anchor" href="#matices" aria-label="Permalink to &quot;Matices&quot;">​</a></h2><ul><li><strong>Auto-inicio:</strong> Si no existe un archivo de configuración, <code>run</code> ejecuta automáticamente el asistente de inicio primero.</li><li><strong>Sin banderas:</strong> El comando <code>run</code> no tiene banderas — toda la configuración proviene del espacio de trabajo.</li><li><strong>Tamaño de terminal:</strong> La TUI requiere una terminal con al menos 80×24 caracteres. Puede no renderizarse correctamente en terminales muy pequeñas.</li><li><strong>Dependencias:</strong> La TUI usa Bubbletea. Funciona a través de SSH y en la mayoría de emuladores de terminal.</li></ul>',25)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
